import React from 'react';

const AnswerOptions = ({ options, onAnswerSelected }) => {
    return (
        <div className="answer-options">
            {options.map((option, index) => (
                <button key={index} onClick={() => onAnswerSelected(option)}>
                    {option}
                </button>
            ))}
        </div>
    );
};

export default AnswerOptions;
